I'm using Python with standard auth and I'm consistently getting a 500
error on GET operations like note_lists. This is my code:

def get_auth(self):
    return "Basic %s" % base64.encodestring(
      ("%s:%s" % (self.account["username"],
self.account["password"]))).strip()

  def connect(self, url, data = None):
    return urllib2.urlopen(urllib2.Request(
      url, data, {"Authorization": self.get_auth()})).read()

  def get_data(self):
    return self.connect(
      "http://api.pownce.com/2.0/note_lists/%s.json?app_key=%s" %
(self.account["username"], API_KEY))

  def transmit_status(self, message):
    return self.connect("http://api.pownce.com/2.0/send/message.json",
        urllib.urlencode({"note_body":message, "app_key": API_KEY,
"note_to": "public"}))


And this is the output:

{
    "error": {
        "status_code": 500,
        "message": "Ack. Server error.",
        "request": "http:\\/\\/api.pownce.com\\/2.0\\/note_lists\\/
segphault.json"
    }
}

The transmit_status method seems to work just fine, but get_data spits
out errors. Any suggestions?
